const s = msg.payload;
const temps = s.temperatures || [];
const maxTemp = temps.length ? Math.max(...temps) : null;
const alerts = s.alerts || [];
const isHV = Array.isArray(alerts) ? alerts.some(a => /high.?v/i.test(String(a))) : !!(alerts.high_voltage);
const isLV = Array.isArray(alerts) ? alerts.some(a => /low.?v/i.test(String(a))) : !!(alerts.low_voltage);
const isHT = Array.isArray(alerts) ? alerts.some(a => /high.?t/i.test(String(a))) : !!(alerts.high_temp);
msg.payload = {
  'Dc/0/Voltage': s.total_voltage || null,
  'Dc/0/Temperature': maxTemp,
  'Info/MaxChargeVoltage': s.charge_voltage || null,
  'Info/MaxChargeCurrent': s.dvcc_max_charge_current || null,
  'Info/MaxDischargeCurrent': s.dvcc_max_discharge_current || null,
  'Alarms/HighVoltage': isHV ? 2 : 0,
  'Alarms/LowVoltage': isLV ? 2 : 0,
  'Alarms/HighTemperature': isHT ? 2 : 0,
  'Connected': s.system_status === 'Running' ? 1 : 0
};
return msg;
